import pathlib,json,copy,yaml,subprocess,tempfile,shutil
class Strict(yaml.SafeLoader):pass
def mapping(loader,node,deep=False):
 loader.flatten_mapping(node);d={}
 for k,v in node.value:
  key=loader.construct_object(k,deep=deep)
  if key in d:raise ValueError('duplicate key')
  d[key]=loader.construct_object(v,deep=deep)
 return d
Strict.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,mapping)
def load(name):return yaml.load(pathlib.Path(name).read_text(encoding='utf-8'),Loader=Strict)
def run(args):
 p=subprocess.run(args,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=15)
 print(p.stdout);print(p.stderr);assert p.returncode==0,'official amtool check failed'
 return p.stdout

CASES=[{'receiver': 'ops <primary> & "值班"', 'status': 'firing', 'alerts': [{'status': 'firing', 'labels': {'alertname': 'Fixture'}, 'annotations': {'summary': 'CPU > 90% & memory < 1GiB'}, 'startsAt': '2026-01-01T00:00:00Z', 'endsAt': '0001-01-01T00:00:00Z', 'generatorURL': 'https://example.invalid', 'fingerprint': '0'}, {'status': 'firing', 'labels': {'alertname': 'Fixture'}, 'annotations': {'summary': '<script>alert("x")</script>'}, 'startsAt': '2026-01-01T00:00:00Z', 'endsAt': '0001-01-01T00:00:00Z', 'generatorURL': 'https://example.invalid', 'fingerprint': '1'}, {'status': 'firing', 'labels': {'alertname': 'Fixture'}, 'annotations': {'summary': '<img src=x onerror="oops()">'}, 'startsAt': '2026-01-01T00:00:00Z', 'endsAt': '0001-01-01T00:00:00Z', 'generatorURL': 'https://example.invalid', 'fingerprint': '2'}, {'status': 'firing', 'labels': {'alertname': 'Fixture'}, 'annotations': {'summary': '中文 & "双引号" <tag> 原样可见'}, 'startsAt': '2026-01-01T00:00:00Z', 'endsAt': '0001-01-01T00:00:00Z', 'generatorURL': 'https://example.invalid', 'fingerprint': '3'}, {'status': 'firing', 'labels': {'alertname': 'Fixture'}, 'annotations': {'summary': '&lt;不是已解码的标签&gt;'}, 'startsAt': '2026-01-01T00:00:00Z', 'endsAt': '0001-01-01T00:00:00Z', 'generatorURL': 'https://example.invalid', 'fingerprint': '4'}], 'groupLabels': {}, 'commonLabels': {}, 'commonAnnotations': {}, 'externalURL': 'https://example.invalid'}, {'receiver': 'empty', 'status': 'firing', 'alerts': [], 'groupLabels': {}, 'commonLabels': {}, 'commonAnnotations': {}, 'externalURL': 'https://example.invalid'}]
from html.parser import HTMLParser
class Document(HTMLParser):
 def __init__(self):super().__init__(convert_charrefs=True);self.stack=[];self.nodes=[];self.current=None;self.articles=0
 def handle_starttag(self,tag,attrs):
  assert not attrs and tag in ['article','h1','p'],'untrusted markup became active HTML'
  if tag=='article':assert not self.stack;self.articles+=1
  else:assert self.stack==['article'];self.current=[tag,'']
  self.stack.append(tag)
 def handle_endtag(self,tag):
  assert self.stack and self.stack.pop()==tag
  if tag in ['h1','p']:self.nodes.append(self.current);self.current=None
 def handle_data(self,data):
  if self.current is not None:self.current[1]+=data
  else:assert not data.strip()
 def handle_comment(self,data):raise AssertionError('unexpected comment markup')
for case in CASES:
 with tempfile.TemporaryDirectory(prefix='am-native-html-') as tmp:
  f=pathlib.Path(tmp)/'case.json';f.write_text(json.dumps(case,ensure_ascii=False),encoding='utf-8')
  prefix=['amtool','template','render','--template.glob='+str(pathlib.Path('notify.tmpl').resolve()),'--template.data='+str(f)]
  rendered=run(prefix+['--template.text={{ template "ops.html" . }}','--template.type=html'])
  document=Document();document.feed(rendered);document.close()
  assert document.articles==1 and not document.stack
  assert document.nodes==[['h1',case['receiver']]]+[['p',a['annotations']['summary']] for a in case['alerts']],'visible text changed'
  text=run(prefix+['--template.text={{ template "ops.text" . }}','--template.type=text'])
  assert text.rstrip('\r\n')=='\n'.join(a['annotations']['summary'] for a in case['alerts']),'text template should preserve literal input'

